css:
.print-heading { display: none !important; }
.print-format, .print-format * { box-sizing: border-box; }

html, body,
.print-format,
.print-format * {
  font-family: Carlito, Arial, Helvetica, sans-serif !important;
}

.print-format {
  font-size: 11pt !important;
  font-weight: 400 !important;
  color: #000 !important;
  padding: 8mm 8mm 8mm 4mm !important;
  margin-top: 8mm;
  margin-right: 8mm;
  margin-bottom: 8mm;
  margin-left: 0;
  letter-spacing: 0 !important;
  background: #fff !important;
}

@page {
  size: A4 portrait;
  margin: 8mm 8mm 8mm 2mm !important;
}

html, body {
  margin: 0 !important;
  padding: 0 !important;
  background: #fff !important;
}

.register {
  width: 100%;
  color: #000;
}

.reg-top {
  display: table;
  width: 100%;
  margin: 3.5mm 0 4.5mm 0;
}
.reg-title {
  display: table-cell;
  vertical-align: bottom;
  font-size: 20pt !important;
  font-weight: 700 !important;
  line-height: 1;
}
.reg-part {
  display: table-cell;
  vertical-align: bottom;
  text-align: right;
  white-space: nowrap;
  font-size: 11pt !important;
  font-weight: 600 !important;
  line-height: 1;
}

.print-format .register .row {
  display: table !important;
  width: 100% !important;
  table-layout: auto;
  border-collapse: collapse;
  height: 5mm;
  margin: 0 0 2.2mm 0 !important;
  padding: 0 !important;
}
.lbl {
  display: table-cell;
  width: 1%;
  white-space: nowrap;
  vertical-align: bottom;
  font-size: 11pt !important;
  font-weight: normal !important;
  color: #000 !important;
  line-height: 1 !important;
  padding: 0 2.5mm 1px 0;
}
.line + .lbl {
  padding-left: 4mm;
}
.line {
  display: table-cell;
  vertical-align: bottom;
  border-bottom: 1px solid #000;
  height: 5mm;
  padding: 0 2px 0.4mm;
  overflow: visible;
  font-size: 11pt !important;
  font-weight: bold !important;
  color: #000 !important;
  line-height: 1;
}
.line:only-child {
  width: 100%;
}
.line:empty:before {
  content: "\00a0";
}
.print-format .lbl,
.print-format span.lbl {
  font-weight: normal !important;
}
.print-format .line,
.print-format span.line {
  font-weight: bold !important;
}
.grow-2 { width: 55%; }
.grow-1 { width: 22%; }

.after-lin {
  height: 4mm;
  margin-bottom: 3.5mm;
}

.bio {
  display: block;
  width: 100%;
  margin-top: 0;
  overflow: visible;
}
.bio::after {
  content: "";
  display: block;
  clear: both;
}
.bio .photo-box {
  float: left;
  margin-right: 6mm;
}
.bio .bio-fields {
  overflow: visible;
  margin-left: 36mm;
}
.photo-box {
  width: 30mm;
  height: 35mm;
  border: 1px solid #000;
  text-align: center;
  overflow: hidden;
  font-size: 11pt !important;
  font-weight: 600 !important;
}
.photo-box .photo-ph {
  height: 35mm;
  line-height: 35mm;
  text-align: center;
}
.photo-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.bio-fields { min-width: 0; }
.print-format .register .bio-fields .row {
  height: 6.8mm !important;
  margin: 0 0 2.6mm 0 !important;
}
.print-format .register .bio-fields .row:last-child {
  margin-bottom: 0 !important;
}

.body { margin-top: 0; }
.body .row { height: 5mm; }


.lines-2 .row { height: 5mm; }
.lines-3 { margin-top: 6.5mm; }
.lines-3 .row { height: 5mm; }

.sigs {
  width: 100%;
  border-collapse: collapse;
  margin-top: 6.5mm;
}
.sigs td.sig-pad,
.sigs td.sig-gap {
  width: 10mm;
  border: none;
  padding: 0;
}
.sig-box {
  height: 32mm;
  border: 1px solid #000;
  text-align: center;
  vertical-align: top;
  font-size: 11pt !important;
  font-weight: normal !important;
  line-height: 1;
  padding: 0 2mm 0;
}
.sig-space {
  height: 24mm;
  line-height: 0;
  font-size: 0;
}
.print-format .sig-box {
  font-weight: normal !important;
}

.notes {
  margin-top: 2.5mm;
  padding-top: 0;
  border-top: none;
  font-size: 9.5pt !important;
  font-weight: 400 !important;
  line-height: 1.2;
  page-break-before: avoid;
  break-before: avoid;
}


.est-line {
  white-space: nowrap;
  overflow: visible !important;
  word-break: normal;
  overflow-wrap: normal;
}

@media screen {
  .print-format {
    box-sizing: border-box !important;
    width: 90% !important;
    max-width: 210mm !important;
    min-height: 297mm !important;
    margin: 0 0 0 76px !important;
    padding: 8mm 8mm 8mm 4mm !important;
    overflow: visible !important;
    border-radius: 0 !important;
  }
}

@media print {
  @page { size: A4 portrait; margin: 8mm 8mm 8mm 2mm !important; }
  html, body {
    margin: 0 !important;
    padding: 0 !important;
    width: auto !important;
    min-height: 0 !important;
    height: auto !important;
  }
  .print-format {
    padding: 0 !important;
    margin: 0 0 0 76px !important;
    width: 90% !important;
    max-width: 202mm !important;
    min-height: 0 !important;
    height: auto !important;
    display: block !important;
  }
  .notes {
    page-break-before: avoid;
    break-before: avoid;
  }
  .action-banner,
  .print-hide {
    display: none !important;
  }
}
